pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(address(this), address(this), address(this)); }

    function testFuzz_property(
        address baseTokenAddr,
        uint128 virtualBaseTokenReserves,
        uint128 virtualNftReserves,
        uint56 changeFee,
        uint16 feeRate,
        bytes32 merkleRoot,
        bool useStolenNftOracle,
        bool payRoyalties
    ) public {
        // Keep only inputs the reference legitimately accepts and that are meaningful:
        // a nonzero base token and a fee rate within the enforced limit.
        vm.assume(baseTokenAddr != address(0));
        feeRate = uint16(bound(feeRate, 0, 5000));

        c.initialize(
            baseTokenAddr,
            address(this),
            virtualBaseTokenReserves,
            virtualNftReserves,
            changeFee,
            feeRate,
            merkleRoot,
            useStolenNftOracle,
            payRoyalties
        );

        // General rule: after a successful initialize, the stored base token
        // equals the one passed in. The mutant stores address(0) instead.
        assertTrue(c.baseToken() == baseTokenAddr);
    }
}

