// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;

    function setUp() public {
        c = new C(address(this), address(this), address(this));
    }

    function testFuzz_property(
        address baseToken,
        address nft,
        uint128 virtualBaseTokenReserves,
        uint128 virtualNftReserves,
        uint56 changeFee,
        uint16 feeRate,
        bytes32 merkleRoot,
        bool useStolenNftOracle,
        bool payRoyalties
    ) public {
        // Admissible domain: a real (nonzero) NFT collection and a fee rate the
        // reference legitimately accepts (<= 5000 bps), otherwise initialize
        // reverts with FeeRateTooHigh for reasons unrelated to the bug.
        vm.assume(nft != address(0));
        vm.assume(feeRate <= 5_000);

        try c.initialize(
            baseToken,
            nft,
            virtualBaseTokenReserves,
            virtualNftReserves,
            changeFee,
            feeRate,
            merkleRoot,
            useStolenNftOracle,
            payRoyalties
        ) {
            // Invariant: after a successful initialization with a nonzero nft
            // argument, the pool's stored nft is nonzero.
            assertTrue(c.nft() != address(0));
        } catch {
            // A revert is only admissible outside the rule's domain; if we got
            // here with an admissible input the rule is vacuously satisfied.
            assertTrue(true);
        }
    }
}

